const payload = $input.item.json.body || $input.item.json;
const data = payload.data || {};
const key = data.key || {};
const message = data.message || {};
const remoteJid = key.remoteJid || '';
const fromMe = key.fromMe === true;
const messageId = key.id || '';
const pushName = data.pushName || '';
const instance = payload.instance || payload.instanceName || '';
const event = payload.event || '';
let messageText = '';
if (message.conversation) messageText = message.conversation;
else if (message.extendedTextMessage && message.extendedTextMessage.text) messageText = message.extendedTextMessage.text;
else if (message.imageMessage && message.imageMessage.caption) messageText = message.imageMessage.caption;
else if (message.videoMessage && message.videoMessage.caption) messageText = message.videoMessage.caption;
else if (message.buttonsResponseMessage && message.buttonsResponseMessage.selectedDisplayText) messageText = message.buttonsResponseMessage.selectedDisplayText;
else if (message.listResponseMessage && message.listResponseMessage.title) messageText = message.listResponseMessage.title;
const phoneNumber = remoteJid.split('@')[0];
const isGroup = remoteJid.includes('@g.us');
const isStatus = remoteJid.includes('status@broadcast');
const isNewsletter = remoteJid.includes('@newsletter');
const hasText = typeof messageText === 'string' && messageText.trim().length > 0;
const timestamp = data.messageTimestamp || Math.floor(Date.now() / 1000);
const isValid = (event === 'messages.upsert' && !fromMe && !isGroup && !isStatus && !isNewsletter && hasText);
const p = String(phoneNumber || '').replace(/[^0-9]/g, '');
let region = 'OTHER';
if (p.startsWith('91')) region = 'INDIA';
else if (p.startsWith('58') || p.startsWith('57') || p.startsWith('34') || p.startsWith('52') || p.startsWith('51') || p.startsWith('56') || p.startsWith('593') || p.startsWith('502') || p.startsWith('503') || p.startsWith('504') || p.startsWith('505') || p.startsWith('506') || p.startsWith('507') || p.startsWith('591') || p.startsWith('598') || p.startsWith('595') || p.startsWith('53') || p.startsWith('1809') || p.startsWith('1829') || p.startsWith('1849') || p.startsWith('971')) region = 'LATAM';
return { json: { event, instance, remoteJid, phoneNumber, fromMe, isGroup, isStatus, isNewsletter, isValid, region, messageId, pushName, messageText: messageText.trim(), messageLength: messageText.trim().length, timestamp } };

// Centralized error handler for failed runs
const err = $input.item.json;
console.error('[DR_RAFAEL_ERROR]', JSON.stringify({
  timestamp: new Date().toISOString(),
  workflow: err.workflow && err.workflow.name,
  executionId: err.execution && err.execution.id,
  errorMessage: err.execution && err.execution.error && err.execution.error.message,
  node: err.execution && err.execution.lastNodeExecuted
}));
return { json: { handled: true } };

// Compute humanized delays
const MIN = 3;
const MAX = 12;
const thinkingDelay = Math.floor(Math.random() * (MAX - MIN + 1)) + MIN;

const inboundLength = ($json.messageText || '').length;
const longInbound = inboundLength > 80;
const extraReadDelay = longInbound ? Math.floor(Math.random() * 4) + 2 : 0;

return {
  json: {
    ...$json,
    thinkingDelay,
    extraReadDelay,
    totalPreDelay: thinkingDelay + extraReadDelay,
    longInbound
  }
};

// Extract assistant reply and prepare for sending
const resp = $input.item.json;

// El nodo AI Agent de n8n guarda la respuesta directamente en 'output'
let text = resp.output || '';

// Mensaje de respaldo limpio y alineado al idioma/bot en caso de falla extrema
if (!text || !text.trim()) {
  text = "Ji, abhi technical issue hai. Kripya thodi der mein try karein.";
}

text = text.trim();

// Pull contextual fields from Parse node
const ctx = $('Parse Incoming Message').item.json;
const phoneNumber = ctx.phoneNumber;

// Optional split for long replies (>180 chars) into 2 natural parts at the closest newline
let parts = [text];
if (text.length > 180) {
  const splitIdx = text.lastIndexOf('\n', Math.floor(text.length / 2) + 30);
  if (splitIdx > 30) {
    parts = [text.slice(0, splitIdx).trim(), text.slice(splitIdx).trim()].filter(Boolean);
  }
}

// Typing simulation: ~55ms per char, capped between 1.5s and 8s per part
// IMPORTANTE: Se agregó Math.round para evitar el error "Invalid input for Wait Amount"
const typingTimes = parts.map(p => Math.round(Math.min(8000, Math.max(1500, p.length * 55))));

return {
  json: {
    phoneNumber: phoneNumber,
    remoteJid: ctx.remoteJid,
    pushName: ctx.pushName,
    originalText: ctx.messageText,
    aiText: text,
    parts: parts,
    typingTimes: typingTimes,
    primaryTypingMs: typingTimes[0]
  }
};

// Final structured log for observability
const ctx = $('Parse Incoming Message').item.json;
const reply = $('Extract & Prepare Reply1 IN1').item.json;

const entry = {
  timestamp: new Date().toISOString(),
  instance: ctx.instance,
  remoteJid: ctx.remoteJid,
  phoneNumber: ctx.phoneNumber,
  pushName: ctx.pushName,
  inbound: ctx.messageText,
  outbound: reply.aiText,
  parts: reply.parts.length,
  status: 'delivered'
};

console.log('[DR_RAFAEL_REDIRECT]', JSON.stringify(entry));
return { json: entry };

